informalexample.programlisting:
#!/bin/bash
if [ -n "$SSH_TTY" ]; then /sbin/vlad session-start ssh fi
current_tty=$(tty 2>/dev/null) if [ -n "$current_tty" ] && echo "$current_tty" | grep -qE '^/dev/tty[0-9]+$'; then /sbin/vlad session-start console fi

#!/bin/csh
if ( $?SSH_TTY ) then /sbin/vlad session-start ssh endif
# Check for system console session set current_tty = `tty` if ( "$current_tty" =~ /dev/tty[0-9]* ) then /sbin/vlad session-start console endif
